// Generated by scripts/sync-help.mjs from pzza-code-web/components/home/playback.ts. Regenerate with `npm run sync:help` rather than editing.
/**
 * Shared playback for the homepage scenes' feature loops, the pattern
 * BroadcastScene set: a scene plays its feature while it is on screen, pauses
 * while it is scrolled away, never plays with reduced motion, and stops for
 * good once the visitor takes over (clicks or types in it).
 *
 * A scene passes an async script that plays one round of its loop using the
 * `wait` it is handed; the hook repeats it. `wait` only resolves while the
 * scene is visible, so a script simply holds wherever it is when the scene
 * leaves the screen and carries on when it comes back. When the scene
 * unmounts or the visitor takes over, the pending `wait` rejects with
 * PlaybackStopped and the script unwinds; nothing after it runs.
 */
import { useEffect, useRef, useState, useSyncExternalStore, type RefObject } from "react";

export class PlaybackStopped extends Error {
  constructor() {
    super("Scene playback stopped");
    this.name = "PlaybackStopped";
  }
}

export type Wait = (ms: number) => Promise<void>;

const sleep = (ms: number) => new Promise<void>((resolve) => window.setTimeout(resolve, ms));

// How often a held script checks whether its scene is back on screen.
const HOLD_POLL_MS = 250;

export function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/**
 * Plays `round` in a loop while `root` is on screen. Pass `stopped` true once
 * the visitor has taken over; the loop ends and does not restart. `onStop`
 * runs when playback ends for any reason, to put transient state (a pressed
 * button, a half-typed field) back.
 */
export function useScenePlayback(
  root: RefObject<HTMLElement>,
  round: (wait: Wait) => Promise<void>,
  { stopped = false, threshold = 0.4, onStop }: { stopped?: boolean; threshold?: number; onStop?: () => void } = {},
) {
  // The latest callbacks, so a re-render never restarts a running loop.
  const roundRef = useRef(round);
  const onStopRef = useRef(onStop);
  useEffect(() => {
    roundRef.current = round;
    onStopRef.current = onStop;
  });

  useEffect(() => {
    const element = root.current;
    if (!element || stopped || prefersReducedMotion()) return;
    let visible = false;
    let cancelled = false;
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
    }, { threshold });
    observer.observe(element);

    const wait: Wait = async (ms) => {
      await sleep(ms);
      while (!visible && !cancelled) await sleep(HOLD_POLL_MS);
      if (cancelled) throw new PlaybackStopped();
    };

    const run = async () => {
      try {
        // Start only once the scene is first on screen.
        await wait(0);
        while (!cancelled) await roundRef.current(wait);
      } catch (error) {
        if (!(error instanceof PlaybackStopped)) throw error;
      }
    };
    void run();

    return () => {
      cancelled = true;
      observer.disconnect();
      onStopRef.current?.();
    };
  }, [root, stopped, threshold]);
}

// No store to subscribe to: only the server and client snapshots differ.
const subscribeNever = () => () => {};

/**
 * For a panel inside a scene (a form, a side panel): true once the visitor
 * has it, from their first click or keystroke anywhere in its scene, and from
 * the start for a panel they opened themselves, since only a panel rendered
 * with the page plays its loop.
 */
export function useVisitorTakeover(root: RefObject<HTMLElement>): boolean {
  // Hydration reads the server snapshot (false); a panel mounted later reads true.
  const openedLater = useSyncExternalStore(subscribeNever, () => true, () => false);
  const [taken, setTaken] = useState(openedLater);
  useEffect(() => {
    const scene = root.current?.closest(".pz");
    if (taken || !scene) return;
    const take = () => setTaken(true);
    scene.addEventListener("pointerdown", take, true);
    scene.addEventListener("keydown", take, true);
    return () => {
      scene.removeEventListener("pointerdown", take, true);
      scene.removeEventListener("keydown", take, true);
    };
  }, [taken, root]);
  return taken;
}
